import type {
  AudioTrackInfo,
  MediaKind,
  NormalizedSource,
  PlayerCapabilities,
  PlayerEvents,
  PlayerOptions,
  QualityLevel,
  TextTrackInfo,
} from "./types.js";

/** Context handed to every engine factory. */
export interface EngineContext {
  /** Element the engine should mount its media surface into. */
  readonly host: HTMLElement;
  readonly source: NormalizedSource;
  readonly options: PlayerOptions;
  readonly emit: <K extends keyof PlayerEvents>(type: K, detail: PlayerEvents[K]) => void;
}

/** The contract every playback engine implements. */
export interface PlayerEngine {
  readonly kind: MediaKind;
  readonly element: HTMLElement | null;
  readonly capabilities: PlayerCapabilities;
  load(): Promise<void>;
  play(): Promise<void>;
  pause(): void;
  seek(time: number): void;
  setVolume(volume: number): void;
  setMuted(muted: boolean): void;
  setPlaybackRate(rate: number): void;
  setQuality?(quality: string | null): void;
  setTextTrack?(id: string | null): void;
  setAudioTrack?(id: string | null): void;
  getQualities?(): readonly QualityLevel[];
  getTextTracks?(): readonly TextTrackInfo[];
  getAudioTracks?(): readonly AudioTrackInfo[];
  getCurrentTime(): number;
  getDuration(): number;
  getBuffered(): number;
  /** Requests an immediate time/duration refresh (embed engines). */
  requestTimeSync?(): void;
  destroy(): void;
}

/** Capabilities shared by native video and audio elements. */
export const NATIVE_CAPABILITIES: PlayerCapabilities = Object.freeze({
  play: true,
  pause: true,
  seek: true,
  volume: true,
  playbackRate: true,
  fullscreen: true,
  pictureInPicture: true,
  textTracks: true,
  audioTracks: true,
  quality: false,
  live: true,
});

/** Capabilities of a still-image surface. */
export const IMAGE_CAPABILITIES: PlayerCapabilities = Object.freeze({
  play: false,
  pause: false,
  seek: false,
  volume: false,
  playbackRate: false,
  fullscreen: true,
  pictureInPicture: false,
  textTracks: false,
  audioTracks: false,
  quality: false,
  live: false,
});

/** Capabilities of an iframe-based embed. */
export const EMBED_CAPABILITIES: PlayerCapabilities = Object.freeze({
  play: true,
  pause: true,
  seek: true,
  volume: true,
  playbackRate: true,
  fullscreen: true,
  pictureInPicture: false,
  textTracks: false,
  audioTracks: false,
  quality: false,
  live: true,
});

/** Best-effort capabilities before an engine is selected. */
export function capabilitiesForKind(kind: MediaKind | null): PlayerCapabilities {
  switch (kind) {
    case "audio":
      return NATIVE_CAPABILITIES;
    case "image":
      return IMAGE_CAPABILITIES;
    case "embed":
      return EMBED_CAPABILITIES;
    case "video":
    default:
      return NATIVE_CAPABILITIES;
  }
}
